void CSealCtrl::TriggerPowerReset()
{
	/* 0x284420: the throw power and its ten pressure readings back to 0 */
	m_trigger_power = 0.0f;

	for (s32 i = 0; i < 10; i++)
		m_buttonreading[i] = 0.0f;
}

